def get_comps(g):
    R,C=len(g),len(g[0]); vis=[[False]*C for _ in range(R)]; res=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]==0 and not vis[i][j]:
                s={(i,j)}; comp=s; changed=True
                while changed:
                    changed=False
                    for a,b in list(comp):
                        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                            x,y=a+dx,b+dy
                            if 0<=x<R and 0<=y<C and g[x][y]==0 and (x,y) not in comp:
                                comp.add((x,y)); changed=True
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                # is every boundary cell of bbox adjacent (orth) to a 2 or OOB? that's equivalent to bbox fully surrounded by 2s
                box_ok = all(
                    g[a][b]==2 or (a==rs[0]-1 and False) for a,b in [ (rs[0]-1,b) for b in range(min(cs),max(cs)+1)] + [(a,cs[0]-1) for a in range(rs[0],rs[-1]+1)] ]
                )
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                cells=[]
                for a in range(r0-1,r1+2):
                    for b in range(c0-1,c1+2):
                        cells.append((a,b))
                box_ok=all(
                    g[a][b]!=0 and g[a][b]!=2 or (a<0 or a>=R or b<0 or b>=C)
                    for a,b in cells if (a,b) not in comp
                )
                # actually simpler: bounding box interior touching border? use: bbox must be strictly inside grid and its outer ring contains no zeros outside comp
                out=[]
                for a in range(r0-1,r1+2):
                    for b in range(c0-1,c1+2):
                        if (a,b) in comp: continue
                        v=g[a][b]
                        if v==0: box_ok=False
                out.append(((sorted(comp)),box_ok))
                res.append(comp,out)
    return res

